  {
    "outboundTag": "direct",
    "protocol": [
      "bittorrent"
    ]
  },
  {
    "outboundTag": "proxy",
    "domain": [
      "domain:yourdomains#你想proxy的domain"
    ]
  },
  {
    "outboundTag": "direct",
    "domain": [
      "geosite:private",
      "geosite:cn",
      "geosite:steam@cn"
    ]
